type Dictionary = typeof vi;
export type TranslationKey = keyof Dictionary;
// Prefer common and navigation copy when domain catalogs reuse the same English phrase.
const phraseMap: Record<string, string> = Object.assign({}, ...Object.values(vi), vi.common, vi.navigation);
export function tr(value: string): string { return phraseMap[value] ?? value; }
export function t<K extends keyof Dictionary>(domain: K, key: keyof Dictionary[K]): string {
  return String(vi[domain][key] ?? String(key));
}
